return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'bs_BA','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:50:38+00:00','po-revision-date'=>'2026-11-05T19:50:38+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Dopunjuje prijevode koji nedostaju za dodatke i teme već instalirane na vašoj stranici.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Taj ekran za otpremanje je zastario: u međuvremenu je pripremljeno drugo otpremanje. Ništa nije poslano. Pregledajte trenutno u Listi prijevoda.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Besplatni uslužni paket daje svakoj stranici ograničen broj slotova za dodatke i teme; slotovi u upotrebi prikazani su u Postavkama nakon što omogućite Babilim.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Zahtjev za prijevod stavlja ovaj dodatak ili temu na jedan od slotova besplatnog uslužnog paketa za ovu stranicu (ograničenje je %1$d za teme i %2$d za dodatke), osim ako je već na jednom. Slot ostaje zauzet, a neuspjeli prijevod ga ne oslobađa.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Zahtjev za prijevod stavlja ovaj dodatak ili temu na jedan od slotova besplatnog uslužnog paketa za ovu stranicu, osim ako je već na jednom. Slot ostaje zauzet, a neuspjeli prijevod ga ne oslobađa.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Ako ovaj dodatak ili tema još nije na jednom od slotova besplatnog uslužnog paketa za ovu stranicu, zahtjev za prijevod stavlja ga na jedan (ograničenje je %1$d za teme i %2$d za dodatke). Slot ostaje zauzet, a neuspjeli prijevod ga ne oslobađa. Nastaviti?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Ako ovaj dodatak ili tema još nije na jednom od slotova besplatnog uslužnog paketa za ovu stranicu, zahtjev za prijevod stavlja ga na jedan. Slot ostaje zauzet, a neuspjeli prijevod ga ne oslobađa. Nastaviti?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d stranica na ovoj mreži postavljena je da izbriše svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za tu stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da zadržite identitet, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim te stranice i ponovo deaktivirajte. Deaktivirati svejedno?' . "\0" . '%1$d stranice na ovoj mreži postavljene su da izbrišu svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za te stranice tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da zadržite identitete, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim svake stranice i ponovo deaktivirajte. Deaktivirati svejedno?' . "\0" . '%1$d stranica na ovoj mreži postavljeno je da izbriše svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za te stranice tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da zadržite identitete, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim svake stranice i ponovo deaktivirajte. Deaktivirati svejedno?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nema šta da se uradi.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Odaberite jezik.','%d failed'=>'%d neuspjelo' . "\0" . '%d neuspjela' . "\0" . '%d neuspjelo','%d not yet tried'=>'%d još nije pokušano' . "\0" . '%d još nisu pokušana' . "\0" . '%d još nije pokušano','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d izvještaj čeka. "Uvijek dijeli" i "Ne dijeli" odnose se na sve njih.' . "\0" . '%d izvještaja čekaju. "Uvijek dijeli" i "Ne dijeli" odnose se na sve njih.' . "\0" . '%d izvještaja čeka. "Uvijek dijeli" i "Ne dijeli" odnose se na sve njih.','%d skipped'=>'%d preskočeno' . "\0" . '%d preskočena' . "\0" . '%d preskočeno','%d succeeded'=>'%d uspjelo' . "\0" . '%d uspjela' . "\0" . '%d uspjelo','%d to install'=>'%d za instalaciju' . "\0" . '%d za instalaciju' . "\0" . '%d za instalaciju','(a public key generated for this site)'=>'(javni ključ generiran za ovu stranicu)','(detected)'=>'(otkriveno)','(generic codes and coordinates only)'=>'(samo generički kodovi i koordinate)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Čišćenje je pauzirano %1$s: %2$s. Ništa nije izbrisano.','A file in the component could not be read, so it was not packaged.'=>'Datoteka u komponenti nije mogla biti pročitana, pa nije upakovana.','A host that serves only one PHP request at a time cannot complete this step.'=>'Host koji obrađuje samo jedan PHP zahtjev istovremeno ne može završiti ovaj korak.','A part of the upload kept failing, so the upload was cancelled.'=>'Jedan dio otpremanja stalno nije uspijevao, pa je otpremanje otkazano.','A translation cannot be requested for that locale on this site right now.'=>'Prijevod za taj jezik trenutno se ne može zatražiti na ovoj stranici.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Upis u indeks prevoda je došao u sukob s drugim zahtjevom %1$s (%2$s) i nije primijenjen; zadržana je najnovija verzija.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Upis u indeks prevoda %1$s (%2$s) nije mogao biti dovršen i nije primijenjen (%3$s).','Account'=>'Račun','Add another language'=>'Dodaj još jedan jezik','Advanced'=>'Napredno','All'=>'Sve','All free-plan slots for this site are used'=>'Sva mjesta u besplatnom paketu za ovu stranicu su iskorištena','All languages'=>'Svi jezici','Already in WordPress core'=>'Već u WordPress jezgru','Already installed.'=>'Već je instalirano.','Always share'=>'Uvijek dijeli','Another installation is running; try again in a moment.'=>'Druga instalacija je u toku; pokušajte ponovo za trenutak.','Automatic installs'=>'Automatske instalacije','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatske instalacije su sada isključene; ponovo ih uključite u postavkama ako ih želite.','Available'=>'Dostupno','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Dostupni prijevodi mogu se instalirati jednim klikom, a prijevodi koji nedostaju mogu se zatražiti. Dok su automatske instalacije uključene, prijevodi koje usluga navodi kao dostupne za jezike kojima upravljate instaliraju se tokom sinhronizacije dvaput dnevno.','Available · %s'=>'Dostupno · %s','Babilim Settings'=>'Postavke za Babilim','Babilim adds translations for every language checked here.'=>'Babilim dodaje prijevode za svaki jezik označen ovdje.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim nije mogao potvrditi privremeni folder izvan web stranice, pa komponenta nije spakovana i ništa nije otpremljeno. Definirajte BABILIM_TEMP_DIR u wp-config.php kao folder s dozvolom pisanja izvan korijenskog direktorija weba (na primjer folder pored javnog direktorija vaše stranice, a ne unutar njega) ili ga zatražite od svog hosta.','Babilim could not finish checking this site.'=>'Babilim nije mogao završiti provjeru ove stranice.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nije mogao završiti omogućavanje (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nije mogao završiti provjeru ove stranice (usluga joj nije mogla pristupiti). Registracija je pauzirana.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nije mogao verifikovati ovu stranicu, pa se ništa neće preuzeti niti instalirati dok verifikacija ne uspije.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nije mogao verificirati ovu web-lokaciju, pa se ništa ne preuzima niti instalira.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim pronalazi dodatke i teme na ovoj web-lokaciji koji nemaju prijevod za vaš jezik i instalira po jedan za svaki.','Babilim has not been enabled for this site yet.'=>'Babilim još nije omogućen za ovu stranicu.','Babilim has not installed any translation for this language.'=>'Babilim nije instalirao nijedan prijevod za ovaj jezik.','Babilim hit an error. Share an error report?'=>'Babilim je naišao na grešku. Podijeliti izvještaj o grešci?','Babilim installed %d translation automatically since your last visit.'=>'Babilim je automatski instalirao %d prijevod od vaše posljednje posjete.' . "\0" . 'Babilim je automatski instalirao %d prijevoda od vaše posljednje posjete.' . "\0" . 'Babilim je automatski instalirao %d prijevoda od vaše posljednje posjete.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim je onemogućen. Ništa se više ne šalje; već instalirani prijevodi nastavljaju raditi.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim je omogućen: ova stranica je verifikovana i pronađena je %d komponenta.' . "\0" . 'Babilim je omogućen: ova stranica je verifikovana i pronađene su %d komponente.' . "\0" . 'Babilim je omogućen: ova stranica je verifikovana i pronađeno je %d komponenti.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim omogućava i provjerava ovu web-lokaciju… (posljednji pokušaj: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim omogućava i provjerava ovu web-lokaciju… Ponovo učitajte stranicu ili sačekajte da se zakazana provjera završi.','Babilim is not enabled.'=>'Babilim nije omogućen.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim je postavljen da izbriše identitet ove stranice kada se dodatak izbriše. Plaćena licenca vezana za ovu stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %s. Da zadržite identitet, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim i ponovo deaktivirajte. Deaktivirati svejedno?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim je ostao bez vremena za ovaj korak i nastavit će pri sljedećoj provjeri.','Babilim settings'=>'Postavke za Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Servis je privremeno odgodio Babilim sinhronizaciju (ograničenje broja zahtjeva); pokušat će ponovo nakon %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim je ažuriran dok je ovo otpremanje čekalo. Stari paket je odbačen; molimo ponovo potvrdite otpremanje.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim će otpremiti ove datoteke iz %1$s (verzija %2$s): svaku .php i .js datoteku, svaku block.json datoteku te readme.txt, readme.md, style.css i theme.json u njegovom glavnom folderu. Koriste se za pronalaženje teksta koji treba prevesti i za identifikaciju dodatka ili teme.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nije dostupan: %s','Back'=>'Nazad','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Jeste li ranije kupili licencu za ovu domenu? Unesite kod za vraćanje koji ste dobili prilikom plaćanja.','Broken placeholder'=>'Neispravan rezervirani tekst','Build'=>'Verzija izgradnje','Built'=>'Izgrađeno','Bulk actions apply only to the selected language of each selected component.'=>'Grupne akcije se primjenjuju samo na odabrani jezik svake odabrane komponente.','Bulk actions apply to every matching language of each selected component.'=>'Grupne akcije se primjenjuju na svaki odgovarajući jezik svake odabrane komponente.','Bulk download:'=>'Grupno preuzimanje:','Bulk request:'=>'Grupni zahtjev:','Bulk update:'=>'Grupno ažuriranje:','Bundled with the plugin'=>'Isporučeno uz dodatak','Bundled with the theme'=>'Isporučeno uz temu','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Klikom na Omogući pristajete da Babilimu pošaljete gore navedene informacije.','By continuing you confirm that you have the right to upload this component.'=>'Nastavkom potvrđujete da imate pravo učitati ovu komponentu.','Cancel'=>'Otkaži','Category'=>'Kategorija','Check again'=>'Provjeri ponovo','Check again now'=>'Provjeri ponovo odmah','Checkout is not available for this site right now.'=>'Plaćanje trenutno nije dostupno za ovu stranicu.','Choose'=>'Odaberi','Choose a category…'=>'Odaberite kategoriju…','Choose a language'=>'Odaberite jezik','Choose a language…'=>'Odaberite jezik…','Clear filters'=>'Očisti filtere','Close'=>'Zatvori','Component'=>'Komponenta','Confirm'=>'Potvrdi','Conflicting keys'=>'Ključevi u sukobu','Continue'=>'Nastavi','Continue next batch (%d left)'=>'Nastavi sa sljedećom grupom (preostalo: %d)','Continuing…'=>'Nastavlja se…','Could not back up %s before replacing it.'=>'Nije moguće napraviti sigurnosnu kopiju %s prije zamjene.','Could not create the package archive.'=>'Nije moguće kreirati arhivu paketa.','Could not determine active components; the existing merged index was left unchanged.'=>'Nije moguće odrediti aktivne komponente; postojeći spojeni indeks je ostavljen nepromijenjen.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nije moguće odrediti instalirane dodatke/teme; čišćenje je preskočeno, ništa nije obrisano.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Nije moguće učitati cijelu listu jezika sa WordPress.org iz servisa, pa trenutno nije moguće dodati nijedan drugi jezik.','Could not move %s into place.'=>'Nije moguće premjestiti %s na odredište.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Nije moguće premjestiti spojeni indeks za \'%s\' na mjesto; prethodni posluženi indeks (ako postoji) je uklonjen umjesto da bude ostavljen napola ažuriran. Za ovaj jezik se ne poslužuje dopuna za zadanu domenu do sljedeće uspješne izgradnje.','Could not open zip: %s'=>'Nije moguće otvoriti zip: %s','Could not prepare %s for rollback.'=>'Nije moguće pripremiti %s za vraćanje na prethodno stanje.','Could not read %s back after moving it into place.'=>'Nije moguće ponovo pročitati %s nakon premještanja na mjesto.','Could not read: %s'=>'Nije moguće pročitati: %s','Could not restore the purchase: %s'=>'Nije moguće vratiti kupovinu: %s','Could not show a new restore code: %s'=>'Nije moguće prikazati novi kod za vraćanje: %s','Could not stage %s'=>'Nije moguće pripremiti %s','Could not stage default/%s'=>'Nije moguće pripremiti default/%s','Could not start checkout: %s'=>'Nije moguće pokrenuti plaćanje: %s','Could not verify entry count for %s'=>'Nije moguće provjeriti broj unosa za %s','Could not write the downloaded package to disk.'=>'Preuzeti paket nije moguće upisati na disk.','Could not write the staged merged index.'=>'Nije moguće zapisati pripremljeni spojeni indeks.','Current translation'=>'Trenutni prijevod','Custom overrides'=>'Vlastita prepisivanja','Danger zone'=>'Opasna zona','Default supplement entry count mismatch.'=>'Broj unosa zadanog dodatka se ne podudara.','Delete all Babilim data on uninstall'=>'Izbriši sve Babilim podatke pri deinstalaciji','Disable Babilim'=>'Onemogući Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Onemogućiti Babilim? Instalirani prevodi se zadržavaju, ali se više neće provjeravati ni preuzimati nove verzije.','Don\'t share'=>'Ne dijeli','Download'=>'Preuzmi','Downloaded and installed.'=>'Preuzeto i instalirano.','Downloading…'=>'Preuzimanje…','Downloads: %1$d/%2$d (%3$s)'=>'Preuzimanja: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Doprinos svake komponente dopuni za zadanu domenu svakog jezika.','Enable Babilim'=>'Omogući Babilim','Enabling…'=>'Omogućavanje…','English (United States)'=>'Engleski (Sjedinjene Američke Države)','Entries'=>'Unosi','Entry count mismatch for %s'=>'Broj unosa se ne podudara za %s','Error reports'=>'Izvještaji o greškama','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Svaki instalirani dodatak/tema: njegov slug, verzija, tekstualne domene, da li je na WordPress.org, njegovi vlastiti uključeni jezici i za koje jezike ste već instalirali Babilim prevod.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Svaki jezik (locale) koji se koristi na ovoj stranici (jezik stranice, instalirani jezični paketi, jezici korisnika i svi koje ručno dodate). Nijedan jezik se ne tretira drugačije od ostalih.','Excluded'=>'Isključeno','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Datoteke s drugim imenima ili ekstenzijama nisu uključene, kao ni folderi uploads, cache, logs, backup, data, vendor, node_modules i languages, skrivene datoteke, niti datoteke čija imena odgovaraju uobičajenim tajnama (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Datoteke koda i dalje mogu sadržavati tekst ili podatke koje ne biste željeli dijeliti; provjerite ih ako niste sigurni. Usluga po prispijeću ponovo uklanja iste vrste datoteka.','Free'=>'Besplatno','Free-plan slots'=>'Mjesta u besplatnom paketu','General'=>'Općenito','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ako je ovo uključeno, deinstalacija također briše identitet ove stranice. Plaćena licenca vezana za ovu stranicu nakon toga se ne može automatski vratiti; morali biste kontaktirati Babilim podršku na %s da biste je povratili.','Included'=>'Uključeno','Included in index'=>'Uključeno u indeks','Install available translations automatically'=>'Automatski instaliraj dostupne prevode','Installed'=>'Instalirano','Installed translations are kept, but no further checks or downloads will run.'=>'Instalirani prijevodi se zadržavaju, ali se više neće provoditi provjere ni preuzimanja.','Installed · %s'=>'Instalirano · %s','Installed · built for %1$s, this site has %2$s'=>'Instalirano · izgrađeno za %1$s, ova stranica ima %2$s','Installed · built for %s'=>'Instalirano · izgrađeno za %s','Installed · built for %s, all free-plan slots for this site are used'=>'Instalirano · izrađeno za %s, sva mjesta u besplatnom paketu za ovu stranicu su iskorištena','Installed · built for %s, new version failed'=>'Instalirano · izrađeno za %s, nova verzija nije uspjela','Installed · built for %s, new version not covered by the free service plan'=>'Instalirano · izrađeno za %s, nova verzija nije obuhvaćena besplatnim uslužnim paketom','Installed · built for %s, new version scheduled'=>'Instalirano · izgrađeno za %s, nova verzija je zakazana','Installed · built for %s, translating the new version…'=>'Instalirano · izgrađeno za %s, prevodi se nova verzija…','Installed · built for a different version'=>'Instalirano · izgrađeno za drugu verziju','Installed · built for a different version, all free-plan slots for this site are used'=>'Instalirano · izrađeno za drugu verziju, sva mjesta u besplatnom paketu za ovu stranicu su iskorištena','Installed · built for a different version, new version failed'=>'Instalirano · izrađeno za drugu verziju, nova verzija nije uspjela','Installed · built for a different version, new version not covered by the free service plan'=>'Instalirano · izrađeno za drugu verziju, nova verzija nije obuhvaćena besplatnim uslužnim paketom','Installed · built for a different version, new version scheduled'=>'Instalirano · izgrađeno za drugu verziju, nova verzija je zakazana','Installed · built for a different version, translating the new version…'=>'Instalirano · izgrađeno za drugu verziju, prevodi se nova verzija…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Pohranjuje ga hosting provajder servisa, a AI modeli ga obrađuju kako bi se dobio prijevod.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Zadrži moja vlastita prepisivanja prevoda pri brisanju svega ili deinstalaciji ovog dodatka.','Language'=>'Jezik','Language:'=>'Jezik:','Languages'=>'Jezici','Languages found on this site: %s.'=>'Jezici pronađeni na ovoj web-lokaciji: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Posljednje čišćenje %1$s: %2$d novooznačeno, %3$d datoteka izbrisano, %4$d zapisa uklonjeno.','Maintenance'=>'Održavanje','Maintenance status is not available right now.'=>'Status održavanja trenutno nije dostupan.','Manifest unavailable: %s'=>'Manifest nije dostupan: %s','Negation reversed'=>'Negacija je obrnuta','No'=>'Ne','No build is available to download for this locale.'=>'Nema dostupne verzije za preuzimanje za ovaj jezik.','No cleanup has run yet.'=>'Čišćenje još nije pokrenuto.','No components match these filters. %s'=>'Nijedna komponenta ne odgovara ovim filterima. %s','No components synced yet.'=>'Još nema sinhronizovanih komponenti.','No installed translation matches.'=>'Nijedan instalirani prijevod ne odgovara.','No language is managed yet.'=>'Još nijedan jezik nije pod upravljanjem.','No pending challenge for this nonce.'=>'Nema izazova na čekanju za ovaj nonce.','No pending challenge to verify.'=>'Nema izazova na čekanju za verifikaciju.','No plugins or themes found.'=>'Nisu pronađeni dodaci ni teme.','No previous build to roll back to.'=>'Nema prethodne izgradnje na koju se može vratiti.','No record for %s'=>'Nema zapisa za %s','No site id is on file to rotate a token for.'=>'Nema spremljenog ID-a stranice za rotiranje tokena.','No — component inactive'=>'Ne — komponenta je neaktivna','No — component removed'=>'Ne — komponenta je uklonjena','No — installed version differs from the active one'=>'Ne — instalirana verzija se razlikuje od aktivne','Not a valid server_build_id: %s'=>'Nevaljan server_build_id: %s','Not covered by the free service plan'=>'Nije obuhvaćeno besplatnim uslužnim paketom','Not installed'=>'Nije instalirano','Not registered yet'=>'Još nije registrovano','Not supported'=>'Nije podržano','Not verified'=>'Nije verifikovano','Note (optional)'=>'Napomena (neobavezno)','Nothing to choose.'=>'Nema ništa za odabir.','Nothing to confirm.'=>'Nema ništa za potvrdu.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Isključeno prema zadanim postavkama: brisanjem dodatka zadržava se identitet ove stranice, pa ga ponovna instalacija može iskoristiti.','One or more served files no longer match the manifest.'=>'Jedna ili više isporučenih datoteka se više ne podudara s manifestom.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednokratna kupovina za ovu stranicu: %1$s %2$s. Uključuje sva buduća ažuriranja prijevoda. Plaćanje obrađuje Paddle u novoj kartici.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Ovo može učiniti samo administrator mreže jer se mijenjaju datoteke prijevoda koje dijele sve stranice na ovoj mreži.','Only plugins and themes can be packaged.'=>'Mogu se pakovati samo dodaci i teme.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Samo kada potvrdite otpremanje za dodatak ili temu koji nisu na WordPress.org: svaku .php i .js datoteku, svaku block.json datoteku te readme.txt, readme.md, style.css i theme.json u glavnom folderu te komponente, kao zip, nakon što se izostave datoteke koje odgovaraju uobičajenim tajnama.','Open Babilim settings'=>'Otvori postavke za Babilim','Original language'=>'Originalni jezik','Original string'=>'Originalni string','Paid'=>'Plaćeno','Partner'=>'Partner','Please check that your site can be reached from the internet, then try again.'=>'Provjerite da je vaša web-lokacija dostupna s interneta, pa pokušajte ponovo.','Please choose a category for this report.'=>'Odaberite kategoriju za ovu prijavu.','Plugin'=>'Dodatak','Plugin · %s'=>'Dodatak · %s','Plugins'=>'Dodaci','Preview'=>'Pregled','Purchase restored. This site is now licensed.'=>'Kupovina je vraćena. Ova stranica je sada licencirana.','Re-parsed entry count did not match the built index.'=>'Broj ponovo parsiranih unosa ne odgovara izgrađenom indeksu.','Re-verify'=>'Ponovo verificiraj','Rebuild index now'=>'Ponovo izgradi indeks','Refusing to write outside the Babilim language-file directory.'=>'Odbijeno pisanje izvan direktorija jezičkih datoteka Babilim.','Registration response was missing required fields.'=>'Odgovoru na registraciju nedostaju obavezna polja.','Registration restarted.'=>'Registracija je ponovo pokrenuta.','Remove'=>'Ukloni','Remove everything Babilim installed'=>'Ukloni sve što je Babilim instalirao','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Ukloniti sve što je Babilim instalirao? Ovo briše sve jezične datoteke koje je Babilim instalirao za svaki dodatak i temu na ovoj stranici.','Remove the %2$s translation of %1$s from this site?'=>'Ukloniti prijevod %2$s za %1$s s ove stranice?','Removed %d installed component.'=>'Uklonjena je %d instalirana komponenta.' . "\0" . 'Uklonjene su %d instalirane komponente.' . "\0" . 'Uklonjeno je %d instaliranih komponenti.','Removed after a failed integrity check'=>'Uklonjeno nakon neuspjele provjere integriteta','Removed.'=>'Uklonjeno.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Uklanja sve jezične datoteke koje je Babilim instalirao za svaki dodatak i temu na ovoj stranici.','Report a problem'=>'Prijavi problem','Report translation'=>'Prijavi prijevod','Request newer translation'=>'Zatraži noviji prijevod','Request translation'=>'Zatraži prevod','Requestable'=>'Može se zatražiti','Requesting…'=>'Traženje…','Restart registration'=>'Ponovo pokreni registraciju','Restore code'=>'Kod za vraćanje','Restore purchase'=>'Vrati kupovinu','Retry request'=>'Ponovi zahtjev','Roll back'=>'Vrati na prethodno','Roll back and report'=>'Vrati na prethodno i prijavi','Roll back and send report'=>'Vrati prethodno stanje i pošalji izvještaj','Roll back the %2$s translation of %1$s to the previous build?'=>'Vratiti prevod %2$s za %1$s na prethodnu verziju?','Rolled back and reported.'=>'Vraćeno na prethodnu verziju i prijavljeno.','Rolled back to the previous build.'=>'Vraćeno na prethodnu verziju.','Rolled back, but the report could not be sent: %s'=>'Vraćeno na prethodnu verziju, ali prijavu nije bilo moguće poslati: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Vraćanje na prethodno stanje prepisalo bi \'%1$s\' (%2$s), što se sada isporučuje za drugu instaliranu komponentu (%3$s); ništa nije promijenjeno.','Rotate-token response was missing site_token.'=>'U odgovoru na rotiranje tokena nedostajao je site_token.','Save changes'=>'Sačuvaj promjene','Scheduled, waiting to be processed'=>'Zakazano, čeka obradu','Search'=>'Pretraži','Search components'=>'Pretraži komponente','Search the installed translations'=>'Pretraži instalirane prijevode','Select all'=>'Odaberi sve','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Odaberite manje komponenti: najviše %1$d operacija po pokretanju (odabrali ste %2$d).','Send report'=>'Pošalji izvještaj','Service plan'=>'Uslužni paket','Settings'=>'Postavke','Share error reports'=>'Dijeli izvještaje o greškama','Share this report'=>'Podijeli ovaj izvještaj','Show a new restore code'=>'Prikaži novi kod za vraćanje','Show the "Report translation" entry in the admin toolbar'=>'Prikaži stavku „Prijavi prijevod“ u administratorskoj alatnoj traci','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Dio teksta ove komponente je ugrađen u kod od strane autora i ne može se prevesti pomoću jezičkog paketa.','Status'=>'Status','Status unknown'=>'Status nepoznat','String context'=>'Kontekst stringa','Suggested translation'=>'Predloženi prevod','Supplementary translation index'=>'Indeks dopunskih prevoda','Supplementary translation index rebuilt.'=>'Dopunski indeks prevoda je ponovo izgrađen.','Supplementary translation maintenance'=>'Održavanje dopunskih prevoda','Supplementary translations'=>'Dopunski prevodi','Sweep aborted without orphaning anything: %s.'=>'Čišćenje prekinuto bez označavanja ijedne stavke osirotjelom: %s.','Sweep complete: %d file deleted.'=>'Čišćenje završeno: %d datoteka obrisana.' . "\0" . 'Čišćenje završeno: %d datoteke obrisane.' . "\0" . 'Čišćenje završeno: %d datoteka obrisano.','Sweep now'=>'Očisti sada','Sync complete.'=>'Sinhronizacija završena.','Thank you. Your report was sent.'=>'Hvala vam. Vaša prijava je poslana.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Ta komponenta nije instalirana na ovoj stranici, pa se za nju ne može zatražiti prevod.','That does not look like a restore code.'=>'Ovo ne izgleda kao kod za vraćanje.','That is not a valid WordPress locale code. Nothing was saved.'=>'To nije valjan WordPress kod jezika. Ništa nije sačuvano.','That is not a valid build identifier.'=>'To nije valjan identifikator verzije.','The change could not be recorded in the translation index; please try again.'=>'Promjena nije mogla biti zabilježena u indeksu prevoda; pokušajte ponovo.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Čišćenje je izvršeno, ali neke njegove promjene nisu mogle biti zabilježene u indeksu prevoda; sljedeće čišćenje će ih ponovo pokušati.','The component has no files that can be uploaded.'=>'Komponenta nema datoteka koje se mogu otpremiti.','The component is not inside the plugins or themes directory.'=>'Komponenta nije unutar direktorija dodataka ili tema.','The component\'s main file was not found.'=>'Glavna datoteka komponente nije pronađena.','The download response was missing a usable location.'=>'U odgovoru na preuzimanje nedostajala je upotrebljiva lokacija.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Stavka otvara panel za pretragu prijevoda koje je Babilim instalirao na ovoj stranici i prijavu jednog od njih.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Polje "%1$s" je predugo: ima %2$d znakova, a ograničenje je %3$d. Ništa nije poslano; skratite ga i pokušajte ponovo.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Zadana domena \'%1$s\' ne odgovara ni slugu manifesta paketa \'%2$s\' ni njegovom text_domain \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Spojeni indeks za \'%s\' je ponovo izgrađen, ali ga indeks prevoda nije mogao zabilježiti; sljedeća izgradnja će pokušati ponovo.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Originalni tekst i prijevodi nastali iz njega bit će dostupni drugim stranicama koje instaliraju istu verziju.','The package declares no main translation file.'=>'Paket ne navodi glavnu datoteku prijevoda.','The package has no %s for its own text domain.'=>'Paket nema %s za vlastitu tekstualnu domenu.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Vrsta \'%1$s\' u manifestu paketa se ne podudara sa zatraženom vrstom \'%2$s\'.','The package produced no servable main translation file.'=>'Paket nije proizveo glavnu datoteku prijevoda koja se može isporučiti.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Tekstualna domena paketa \'%1$s\' ne podudara se s kopijom komponente na ovoj stranici (\'%2$s\'), pa paket nije instaliran.','The packaged component could not be read.'=>'Upakovana komponenta nije mogla biti pročitana.','The registration challenge is not in the expected form.'=>'Izazov za registraciju nije u očekivanom obliku.','The report could not be sent.'=>'Izvještaj nije mogao biti poslan.','The search could not be completed.'=>'Pretraga nije mogla biti završena.','The service asked this site to wait before syncing again.'=>'Servis je zatražio da ova stranica pričeka prije ponovne sinhronizacije.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Servis nije mogao doprijeti do vaše stranice. Zahtjev vjerovatno blokira zaštitni zid, sigurnosni dodatak ili pravilo hosta; molimo dozvolite zahtjeve prema /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Ponuda servisa za otpremanje bila je nepotpuna.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Tekstualna domena \'%1$s\' (%2$s) već se isporučuje za drugu instaliranu komponentu (%3$s); ništa nije instalirano.','The upload is kept until you ask Babilim to delete it.'=>'Učitani sadržaj se čuva dok od Babilima ne zatražite da ga izbriše.','Theme'=>'Tema','Theme · %s'=>'Tema · %s','Themes'=>'Teme','There is no upload in progress.'=>'Nema učitavanja u toku.','There is no upload waiting for confirmation.'=>'Nema učitavanja koje čeka potvrdu.','These are the languages this site uses. You can change them in %s.'=>'Ovo su jezici koje ova stranica koristi. Možete ih promijeniti u %s.','These fields will be sent:'=>'Ova polja će biti poslana:','This build is not one this site currently knows about for this component/locale.'=>'Ova stranica trenutno ne poznaje ovu verziju za ovu komponentu/jezik.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ova komponenta ne navodi broj verzije, pa se za nju ne može zatražiti prevod.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ova komponenta je veća nego što servis prihvata, pa se ne može otpremiti.','This component was already uploaded. Babilim is checking it now.'=>'Ova komponenta je već otpremljena. Babilim je upravo provjerava.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Broj verzije ove komponente duži je od %d znakova, što Babilim ne može obraditi, pa se za nju ne može zatražiti prevod.','This issues a new restore code and the previous one stops working. Continue?'=>'Ovo izdaje novi kod za vraćanje, a prethodni prestaje raditi. Nastaviti?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ova mreža ima previše stranica da bi se provjeravale jedna po jedna, a neke od njih možda su postavljene da izbrišu svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za takvu stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %s. Da zadržite identitete, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim svake stranice i ponovo deaktivirajte. Deaktivirati svejedno?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Verzija samog ovog dodatka, kako bi vam usluga mogla reći da ga ažurirate ako je prestar za komunikaciju.','This report does not name a valid plugin or theme and locale.'=>'Ova prijava ne navodi važeći dodatak ili temu i jezik.','This report does not name an installed string.'=>'Ovaj izvještaj ne navodi instaliran string.','This report is missing a valid build to report against.'=>'Ovoj prijavi nedostaje važeća verzija na koju se prijava odnosi.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Ovaj izvještaj bit će javno objavljen na GitHub-u i treće strane ga mogu zadržati.','This restore code was not recognised for this site.'=>'Ovaj kod za vraćanje nije prepoznat za ovu stranicu.','This site already has an active registration that can no longer be recovered automatically.'=>'Ova stranica već ima aktivnu registraciju koja se više ne može automatski oporaviti.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Ova stranica ima %1$d komponenti na %2$d jezika, što zahtijeva %3$d paketa provjere; Babilim može obraditi najviše %4$d po pokretanju. Smanjite broj upravljanih jezika u Postavkama ili deaktivirajte neiskorištene dodatke i teme, zatim sada pritisnite Provjeri ponovo.','This site has no purchase to show a code for.'=>'Ova stranica nema kupovinu za koju bi se mogao prikazati kod.','This site is already licensed. Reload the page.'=>'Ova stranica je već licencirana. Ponovo učitajte stranicu.','This site is not registered with Babilim yet.'=>'Ova stranica još nije registrirana kod Babilima.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Ova stranica premašuje veličinu koju servis prihvata u jednoj sinhronizaciji, pa su neke stavke izostavljene: %1$d komponenti i %2$d jezika.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Ova stranica je dio multisite mreže, koja ne instalira nove prijevode automatski. Već instalirani prijevodi se i dalje ažuriraju.','This site is verified.'=>'Ova web-lokacija je verificirana.','This site must be verified first.'=>'Ova stranica prvo mora biti verifikovana.','This site\'s URL, so the service can verify you own it.'=>'URL ove stranice, kako bi usluga mogla provjeriti da ste vi njen vlasnik.','This site\'s address is too long for Babilim to register.'=>'Adresa ove stranice je predugačka da bi je Babilim registrovao.','This site\'s configured locale.'=>'Konfigurirani jezik (locale) ove stranice.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Javni ključ instalacije ove stranice, koji služi kao dokaz da zahtjevi zaista dolaze s ove stranice. Šalje se isključivo javni dio.','This site\'s locale code is not one Babilim can register.'=>'Kod jezika ove stranice nije takav da ga Babilim može registrovati.','This string can\'t be reported from this site.'=>'Ovaj string se ne može prijaviti s ove stranice.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Ovaj string nije među prijevodima instaliranim na ovoj stranici. Pretražite ponovo i odaberite ga s liste.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Ovaj prijevod je ažuriran nakon vaše pretrage. Pretražite ponovo i odaberite string s nove liste.','To translate this component, Babilim needs its source.'=>'Da bi preveo ovu komponentu, Babilim treba njen izvorni kod.','Too many attempts. Try again tomorrow.'=>'Previše pokušaja. Pokušajte ponovo sutra.','Too many reports today. Try again tomorrow.'=>'Previše prijava danas. Pokušajte ponovo sutra.','Too many requests.'=>'Previše zahtjeva.','Toolbar'=>'Alatna traka','Translating…'=>'Prevođenje…','Translation does not load'=>'Prevod se ne učitava','Translation failed'=>'Prevođenje nije uspjelo','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Datoteke prijevoda koje stavite u %s uvijek imaju prednost nad Babilimovim. Zadržavaju se osim ako ovo ne isključite.','Translation requested.'=>'Prijevod je zatražen.','Translations'=>'Prijevodi','Type'=>'Vrsta','Type at least 2 characters to search.'=>'Unesite najmanje 2 znaka za pretragu.','Unexpected HTTP %d response.'=>'Neočekivan HTTP odgovor %d.','Uninstall'=>'Deinstalacija','Unknown kind: %s'=>'Nepoznata vrsta: %s','Unsafe domain: %s'=>'Nesiguran domen: %s','Unsafe locale: %s'=>'Nesiguran jezik (locale): %s','Unsafe slug: %s'=>'Nesiguran slug: %s','Unsafe text_domain: %s'=>'Nesiguran text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Do 20 dijagnostičkih događaja na čekanju (npr. datoteka koja nije prošla provjeru integriteta), svaki samo kao kod, komponenta i jezik, nikada sadržaj stringova ni prevedeni tekst.','Update'=>'Ažuriraj','Update available'=>'Dostupno ažuriranje','Updates'=>'Ažuriranja','Updating…'=>'Ažuriranje…','Upgrade this site'=>'Nadogradi ovu stranicu','Upload and request'=>'Učitaj i zatraži','Upload cancelled.'=>'Otpremanje je otkazano.','Upload complete — translation requested.'=>'Otpremanje je završeno — prevod je zatražen.','Upload expired before it finished'=>'Otpremanje je isteklo prije završetka','Upload in progress — continue or cancel'=>'Otpremanje je u toku — nastavite ili otkažite','Upload this component?'=>'Učitati ovu komponentu?','Upload was not accepted'=>'Otpremanje nije prihvaćeno','Uploading'=>'Učitavanje','Uploading part %1$d of %2$d…'=>'Učitavanje dijela %1$d od %2$d…','Uploading…'=>'Učitavanje…','Verified'=>'Verifikovano','Verify response was missing site_token.'=>'U odgovoru na verifikaciju nedostajao je site_token.','Version %s'=>'Verzija %s','What is sent when Babilim checks this site'=>'Šta se šalje kada Babilim provjerava ovu stranicu','What is sent when you enable Babilim'=>'Šta se šalje kada omogućite Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Kada nešto zakaže unutar Babilima, pošaljite izvještaj o grešci Babilim usluzi kako bi mogao biti objavljen kao javni problem na GitHub-u. Izvještaj se šalje kao da dolazi s ove stranice, s istom autentifikacijom kao i svaki drugi zahtjev prema Babilim usluzi. Usluga kao javni problem na GitHub-u objavljuje samo kod greške i verzije; javni problem ne sadrži adresu stranice, sadržaj ni putanje datoteka. Isključeno prema zadanim postavkama.','Where you saw this (optional)'=>'Gdje ste ovo vidjeli (neobavezno)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Dok je ovo uključeno, prijevodi koje usluga navodi kao dostupne za jezike kojima upravljate instaliraju se tokom sinhronizacije dvaput dnevno.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Pogrešno za ovaj kontekst','Wrong meaning'=>'Pogrešno značenje','Wrong plural form'=>'Pogrešan oblik množine','Wrong term'=>'Pogrešan termin','Yes'=>'Da','You are not allowed to do this.'=>'Nemate dozvolu za ovu radnju.','Your PHP version, for compatibility.'=>'Vaša verzija PHP-a, radi kompatibilnosti.','Your WordPress version, to serve compatible translation files.'=>'Vaša verzija WordPressa, radi isporuke kompatibilnih datoteka prijevoda.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Vaš novi kod za vraćanje: %s. Sačuvajte ga na sigurnom mjestu — prethodni kod više ne radi.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Vaš izvještaj automatski obrađuju AI modeli i može poboljšati ovaj prijevod za druge stranice.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Vaša stranica je odgovorila, ali ne očekivanim sadržajem. REST API možda mijenja drugi dodatak ili je ta krajnja tačka keširana; molimo isključite /wp-json/babilim/v1/challenge iz keširanja i prepisivanja.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Vaša web-lokacija je predugo odgovarala. Pokušajte ponovo kasnije i provjerite da host nije prespor ili preopterećen.','Zip has no manifest.json.'=>'Zip nema manifest.json.','Zip is missing expected default file: %s'=>'Zip nema očekivanu zadanu datoteku: %s','Zip is missing expected file: %s'=>'Zip nema očekivanu datoteku: %s','_manifest.json has an unexpected structure'=>'_manifest.json ima neočekivanu strukturu','could not read _manifest.json: %s'=>'nije moguće pročitati _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest nedostaje ili ima nevažeće polje \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' u expected_manifest nije važeći ID izgradnje.','failed to parse _manifest.json: %s'=>'nije uspjelo parsiranje _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'osirotjele bi bile %1$d od %2$d upravljanih komponenti (više od polovine)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'osirotjele bi bile sve upravljane komponente tipa %1$s (%2$d od %2$d)','l10n.php entry count mismatch for %s'=>'Broj unosa u l10n.php se ne podudara za %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ima nevažeći \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ima nevažeći \'default_domain_files\'.','manifest.json in the zip is not valid JSON.'=>'manifest.json u zip datoteci nije valjan JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json nedostaje ili ima nevažeće polje \'%s\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json nedostaje ili ima nevažeći \'build_no\'.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json nedostaje ili ima nevažeće \'entries\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json nedostaje ili ima nevažeće \'extra_domains\'.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json nedostaje ili ima nevažeće \'files\'.','manifest.json\'s \'%s\' does not match the expected value.'=>'Polje \'%s\' u manifest.json se ne podudara s očekivanom vrijednošću.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' u manifest.json nije važeći niz verzije.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' u manifest.json mora biti \'plugin\' ili \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' u manifest.json nije važeći ID izgradnje.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' u manifest.json mora biti \'published\'.','nonce must be a hexadecimal string.'=>'nonce mora biti heksadecimalni niz.','per day'=>'dnevno','rc_…'=>'rc_…','sha256 mismatch for %s'=>'sha256 se ne podudara za %s','sha256 mismatch for default/%s'=>'sha256 se ne podudara za default/%s','component kind in the sweep brake messageplugin'=>'dodatak','component kind in the sweep brake messagetheme'=>'temu','problem report categoryOther'=>'Ostalo','translation statusAvailable'=>'Dostupno','translation statusInstalled'=>'Instalirano']];